// --- BROKEN: std::ref() on a stack local that dies too early ---
void brokenLauncher() {
    int localCounter = 42; // Lives on brokenLauncher's stack
    PcoThread t(workerRef, std::ref(localCounter));
    // BUG: brokenLauncher() returns immediately without join()!
    // localCounter is destroyed while 't' still holds a reference to it.
}

// --- SAFE: Pass by value OR join() before scope exits ---
void safeLauncher() {
    int localCounter = 42;
    PcoThread t(workerVal, localCounter); // Copied by value: safe!
    t.join(); // Even if using std::ref/pointer, joining guarantees lifetime.
}

