typedef struct { int a; int b; } struct_t;
void task1(struct_t& var) { std::cout << "Task 1: " << var.a << ", " << var.b << std::endl; }
void task2(int val)       { std::cout << "Task 2: " << val << std::endl; }

// EXAMPLE 1 (Sequential Trap!): join() immediately after each creation
int main_sequential_trap() {
    struct_t v = {1, 2};
    PcoThread thread1(task1, std::ref(v));
    thread1.join(); // Blocks here! thread2 hasn't even been created yet!
    PcoThread thread2(task2, 3);
    thread2.join(); // Runs strictly AFTER thread1 finishes (zero concurrency)
    return 0;
}

// EXAMPLE 2 (Concurrent): Launch all threads first, THEN join all
int main_concurrent() {
    struct_t v = {1, 2};
    PcoThread thread1(task1, std::ref(v));
    PcoThread thread2(task2, 3); // thread1 and thread2 run concurrently!
    thread1.join();
    thread2.join();
    return 0;
}

// EARLY RETURN TRAP: main() returns without join()
void taskFunction() {
    for (int i = 0; i <= 100; i++) std::cout << "Coucou" << std::endl;
}
int main_missing_join() {
    PcoThread thread(taskFunction);
    return 0; // DANGER: Terminates the ENTIRE process and kills 'thread' immediately!
}
// Fix: Call thread.join(); before return 0;

static int counter = 1;

void taskFunction() {
    while (true) {
        counter++;
        if (counter % 100 == 0) {
            // Check cancellation flag only at a safe point (every 100 iterations)
            if (PcoThread::thisThread()->stopRequested())
                return; // Clean self-termination -> wakes join()
        }
    }
}

int main(int argc, char* argv[]) {
    PcoThread thread(taskFunction);
    PcoThread::usleep(5000); // Sleep 5000 microseconds (5 ms)
    thread.requestStop();    // Politely ask 'thread' to stop
    thread.join();           // Wait for 'thread' to reach safe point and return
    std::cout << "Counter: " << counter << std::endl;
    return 0;
}

PcoThread* thread1 = nullptr;
PcoThread* thread2 = nullptr;

// --- EXAMPLE 2 (SAFE): thread2 stops thread1 ---
void task1_safe() {
    while (true) {
        if (PcoThread::thisThread()->stopRequested()) return;
    }
}
void task2_safe() {
    thread1->requestStop(); // SAFE: thread1 was assigned BEFORE thread2 was created
}
int main_safe() {
    thread1 = new PcoThread(task1_safe);
    thread2 = new PcoThread(task2_safe);
    thread1->join(); thread2->join();
    delete thread1; delete thread2;
    return 0;
}

// --- EXAMPLE 3 (RACE CONDITION CRASH!): thread1 stops thread2 ---
void task1_crash() {
    thread2->requestStop(); // DANGER: thread2 may STILL be nullptr!
}
void task2_crash() {
    while (true) {
        if (PcoThread::thisThread()->stopRequested()) return;
    }
}
int main_crash() {
    thread1 = new PcoThread(task1_crash); // Launches IMMEDIATELY!
    // Race window: task1_crash() can run BEFORE thread2 is assigned below!
    thread2 = new PcoThread(task2_crash);
    thread1->join(); thread2->join();
    delete thread1; delete thread2;
    return 0;
}

